schema_validation.schema_text:
entity User {
    mid: String,
    name: String,
    email: String,
};

entity Patient in [User] {
    providerList: ProviderList,
};

entity Hcp in [User];

entity Lhcp in [Hcp] {
    specialty: String,
    hospitals: Set<Hospital>,
    zipCode?: String,
};

entity Administrator in [User];

entity Uap in [User];

entity EmergencyResponder in [User];

entity PublicHealthAgent in [User];

entity PersonalRepresentative in [User] {
    representedPatients: Set<Patient>,
};

entity Hospital;

entity ProviderList {
    patient: Patient,
    providers: Set<Hcp>,
};

entity ProviderDesignation {
    patient: Patient,
    lhcp: Lhcp,
    isDesignated: Bool,
};

entity MedicalRecord {
    patient: Patient,
    hasFamilyHistory: Bool,
    hasPersonalHealthInformation: Bool,
    hasImmunizations: Bool,
    hasOfficeVisitInformation: Bool,
};

entity DemographicInformation {
    patient: Patient,
};

entity Credential {
    user: User,
    hasPassword: Bool,
    hasSecurityQuestion: Bool,
};

entity AccessLog {
    patient: Patient,
    accessorName: String,
    accessorRoleRelativeToPatient: String,
    accessTimestamp: datetime,
    transactionType: String,
};

entity Session {
    user: User,
    isActive: Bool,
    inactivityPeriodLength: duration,
    lastActivityAt: datetime,
};

action createPatient appliesTo {
    principal: [Hcp],
    resource: [Patient],
    context: {
        session: Session,
    },
};

action editPatientData appliesTo {
    principal: [Hcp],
    resource: [Patient],
    context: {
        session: Session,
        fieldName: String,
    },
};

action enterCredential appliesTo {
    principal: [Hcp, User],
    resource: [Credential],
    context: {
        session: Session,
        credentialField: String,
    },
};

action editCredential appliesTo {
    principal: [Hcp, User],
    resource: [Credential],
    context: {
        session: Session,
        credentialField: String,
    },
};

action viewCredential appliesTo {
    principal: [Hcp, User],
    resource: [Credential],
    context: {
        session: Session,
        credentialField: String,
    },
};

action createLhcp appliesTo {
